        static
        void kernel_cholesky(int n,
                     DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
        {
          int i, j, k;

        #pragma scop
          for (i = 0; i < _PB_N; i++) {
             //j<i
             for (j = 0; j < i; j++) {
                DATA_TYPE temp = (DATA_TYPE)0.0;
                #pragma omp simd reduction(+:temp)
                for (k = 0; k < j; k++) {
                   temp += A[i][k] * A[j][k];
                }
                A[i][j] = (A[i][j] - temp) / A[j][j];
             }
             // i==j case
             DATA_TYPE temp_diag = (DATA_TYPE)0.0;
             #pragma omp simd reduction(+:temp_diag)
             for (k = 0; k < i; k++) {
                temp_diag += A[i][k] * A[i][k];
             }
             A[i][i] = A[i][i] - temp_diag;
             A[i][i] = SQRT_FUN(A[i][i]);
          }
        #pragma endscop

